#!/usr/bin/env python3
"""Inventory and scan project files; output is evidence for review, not a legal ruling."""
import csv
import hashlib
import json
import os
import re
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "target" / "legal-audit"
EXCLUDED = {"target", "artifacts", "dist", "versions", "Paper-26.3", ".git"}
PATTERNS = {
    "extraction": re.compile(r"vineflower|decompil|auto.extract|extract(?:ed|ion)|client data|vanilla data", re.I),
    "generated": re.compile(r"auto.generated|generated by|do not edit", re.I),
    "license": re.compile(r"SPDX-License-Identifier|copyright|licensed under|license\s*[=:]", re.I),
    "upstream": re.compile(r"https?://(?:github\.com|gitlab\.com|crates\.io)/[^\s\"'<>)]{3,}", re.I),
}


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    audit_names = {"FILE_REVIEW_CURRENT.csv", "LOCAL_ARTIFACTS_INDEX.csv", "FILE_REVIEW_SUMMARY.json"}
    records, artifacts, errors = [], [], []
    for folder, dirs, files in os.walk(ROOT, followlinks=False):
        base = Path(folder)
        dirs[:] = [d for d in dirs if not (base / d).is_symlink()]
        for name in files:
            path = base / name
            rel = path.relative_to(ROOT)
            if path.parent == OUT and name in audit_names:
                continue
            try:
                st = path.lstat()
                if path.is_symlink():
                    errors.append({"path": rel.as_posix(), "error": "symlink not followed"})
                    continue
                if rel.parts[0] in EXCLUDED or "target" in rel.parts:
                    artifacts.append({"path": rel.as_posix(), "size_bytes": st.st_size, "review": "metadata only; content and rights not reviewed"})
                    continue
                data = path.read_bytes()
                sha = hashlib.sha256(data).hexdigest()
                text_data = data.decode("utf-8", errors="replace")
                hits = []
                if b"\0" not in data[:4096]:
                    for line_num, line in enumerate(text_data.splitlines(), 1):
                        for category, pattern in PATTERNS.items():
                            if pattern.search(line):
                                hits.append(f"{category}:{line_num}")
                if rel.parts[:3] == ("RadCore", "data", "mc777") or rel.as_posix() in {
                    "RadCore/src/mc777_data.rs", "RadCore/src/packet/configuration_core_tags.rs", "RadCore/src/packet/configuration_static_tags.rs"
                }:
                    status = "NEEDS_REVIEW_SOURCE_OR_DERIVED_DATA"
                    action = "Trace inputs, verify rights and release inclusion; do not publish on assumption"
                elif rel.parts[0] in {"config", "radonfigs", "radons"} or rel.name in {"rad.properties", "radserver.toml", "radlimbo.toml", "radproxy.toml", "verify-jump.log"}:
                    status = "LOCAL_DATA_REVIEW"
                    action = "Preserve; exclude local state from release unless separately reviewed"
                else:
                    status = "AUTHORSHIP_AND_RIGHTS_UNVERIFIED"
                    action = "Check owner/source, dependency conditions and intended release"
                records.append({"path": rel.as_posix(), "bytes": len(data), "sha256": sha, "status": status, "evidence_markers": ";".join(hits[:30]), "next_action": action, "review_scope": "full-file automated text-marker scan and hash; not a legal or manual line-by-line review"})
            except (OSError, ValueError) as exc:
                errors.append({"path": rel.as_posix(), "error": type(exc).__name__})
    for filename, rows, fields in [
        ("FILE_REVIEW_CURRENT.csv", records, ["path", "bytes", "sha256", "status", "evidence_markers", "next_action", "review_scope"]),
        ("LOCAL_ARTIFACTS_INDEX.csv", artifacts, ["path", "size_bytes", "review"]),
    ]:
        with (OUT / filename).open("w", encoding="utf-8-sig", newline="") as stream:
            writer = csv.DictWriter(stream, fieldnames=fields)
            writer.writeheader()
            writer.writerows(rows)
    summary = {"source_files_scanned": len(records), "source_statuses": dict(Counter(r["status"] for r in records)), "artifact_files_metadata_only": len(artifacts), "errors_or_symlinks": errors, "limitations": "Automated marker scan, not authorship verification or legal analysis; artifacts not opened, nested archives not enumerated; provenance cannot be established from absent markers."}
    (OUT / "FILE_REVIEW_SUMMARY.json").write_text(json.dumps(summary, indent=2, ensure_ascii=False), encoding="utf-8")
    print(json.dumps({k: v for k, v in summary.items() if k != "errors_or_symlinks"}, ensure_ascii=False))
    print("errors_or_symlinks:", len(errors))


if __name__ == "__main__":
    main()
